import json

def horizontal_flip():
    """Swap left and right quadrants"""
    out = [[0]*14 for _ in range(14)]

    # Original positions:
    # Color 9: 5x3 at top-left (1-5, 1-3)
    # Color 7: 5x5 at top-right (2-6, 7-11)
    # Color 4: 3x3 at bottom-left (9-11, 2-4)
    # Color 2: 6x3 at bottom-right (7-12, 10-12)

    # After horizontal swap (swap columns around center):
    # Color 9 → top-right equivalent position
    # Color 7 → top-left equivalent
    # Color 4 → bottom-right equivalent
    # Color 2 → bottom-left equivalent

    # Color 9 (5x3) → top-left mirrored (1-5, 11-13 ≈ 1-5, 8-10 adjusted)
    for r in range(1, 1+5):
        for c in range(8, 8+3):
            if r < 14 and c < 14:
                out[r][c] = 9

    # Color 7 (5x5) → top-left equivalent (2-6, 2-6)
    for r in range(2, 2+5):
        for c in range(2, 2+5):
            out[r][c] = 7

    # Color 4 (3x3) → bottom-right equivalent (12-14, 8-10)
    for r in range(12, 12+3):
        for c in range(8, 8+3):
            if r < 14 and c < 14:
                out[r][c] = 4

    # Color 2 (6x3) → bottom-left equivalent (7-12, 2-4)
    for r in range(7, 7+6):
        for c in range(2, 2+3):
            out[r][c] = 2

    return out

