def cycle_positions():
    """Rotate rectangle positions by one step clockwise:
    top-left → top-right → bottom-right → bottom-left → top-left
    """
    out = [[0]*14 for _ in range(14)]

    # 9 (5x3) top-left → top-right position
    for r in range(2, 2+5):
        for c in range(7, 7+3):
            if r < 14 and c < 14:
                out[r][c] = 9

    # 7 (5x5) top-right → bottom-right position  
    for r in range(7, 7+5):
        for c in range(10, 10+5):
            if r < 14 and c < 14:
                out[r][c] = 7

    # 2 (6x3) bottom-right → bottom-left position
    for r in range(9, 9+6):
        for c in range(1, 1+3):
            if r < 14 and c < 14:
                out[r][c] = 2

    # 4 (3x3) bottom-left → top-left position
    for r in range(2, 2+3):
        for c in range(1, 1+3):
            out[r][c] = 4

    return out

